# kaliru plugin layer: mirror of Kalico klippy.queuelogger (generated by tools/gen_mirror.py)
import _k
import logging.handlers
import queue
import threading
import time

MainQueueHandler = None

class QueueHandler(logging.Handler):
    def __init__(self, queue):
        logging.Handler.__init__(self)
        self.queue = queue

    def emit(self, record):
        try:
            self.format(record)
            record.msg = record.message
            record.args = None
            record.exc_info = None
            self.queue.put_nowait(record)
        except Exception:
            self.handleError(record)

class QueueListener(logging.handlers.TimedRotatingFileHandler):
    def __init__(self, filename, rotate_log_at_restart):
        if rotate_log_at_restart:
            logging.handlers.TimedRotatingFileHandler.__init__(
                self, filename, when="S", interval=60 * 60 * 24, backupCount=5
            )
        else:
            logging.handlers.TimedRotatingFileHandler.__init__(
                self, filename, when="midnight", backupCount=5
            )
        self.bg_queue = queue.Queue()
        self.bg_thread = threading.Thread(target=self._bg_thread)
        self.bg_thread.start()
        self.rollover_info = {}

    def _bg_thread(self):
        while True:
            record = self.bg_queue.get(True)
            if record is None:
                break
            self.handle(record)

    def stop(self):
        self.bg_queue.put_nowait(None)
        self.bg_thread.join()

    def set_rollover_info(self, name, info):
        if info is None:
            self.rollover_info.pop(name, None)
            return
        self.rollover_info[name] = info

    def clear_rollover_info(self):
        self.rollover_info.clear()

    def doRollover(self):
        before = self.rolloverAt
        logging.handlers.TimedRotatingFileHandler.doRollover(self)
        if self.rolloverAt <= before:
            return
        lines = [
            self.rollover_info[name] for name in sorted(self.rollover_info)
        ]
        lines.append(
            "=============== Log rollover at %s ==============="
            % (time.asctime(),)
        )
        self.emit(
            logging.makeLogRecord(
                {"msg": "\n".join(lines), "level": logging.INFO}
            )
        )

def setup_bg_logging(filename, debuglevel, rotate_log_at_restart):
    return _k.fcall(7030, filename, debuglevel, rotate_log_at_restart)

def clear_bg_logging():
    return _k.fcall(7031)


__getattr__ = _k.module_getattr(__name__)
